		/// - Engine is required to be running.
		/// - The capture is required to have status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_STOPPED.
		/// - The capture is required to have accumulated sufficient data to switch from the
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_PREPARING
		/// status to the
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_CAPTURING
		/// status.
		/// - The generation configuration is required to be valid. It has to provide the path to an existing output directory
		/// that can be written to, and it has to provide a valid target name. If database generation is enabled, then the
		/// configuration has to hold valid credentials for communication with the Vuforia server.
		/// - For aligned generation, the generation configuration must also provide the path to a valid Area Target database
		/// and the name of the target that will be used for alignment. If generation is successful, then the newly generated
		/// Area Target will be aligned to the alignment target coordinate system.
		/// If all the requirements are met, this function starts Area Target generation in the background, switches the capture to status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_GENERATING,
		/// and returns VU_SUCCESS. If any of the requirements
		/// are not met, VU_FAILED is returned and the optional error parameter will hold an error code that reflects the cause of the error.
		/// Area Target generation runs in the background. When it completes, the capture switches back
		/// to status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_STOPPED.
		/// On successful Area Target
		/// generation, status info reports
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_INFO_GENERATION_SUCCESS.
		/// If Area Target generation failed, then status info holds one of
		/// the values prefixed with
		/// @ref VuAreaTargetCaptureStatusInfo
		/// &quot;VU_AREA_TARGET_CAPTURE_STATUS_INFO_GENERATION_ERROR&quot;
		/// to report on the failure cause. If Area Target generation was canceled, status info holds the value
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_INFO_GENERATION_CANCELED.
		/// If database generation is enabled, then a network connection is required.
		/// If Engine is stopped while Area Target generation is running, then Area Target generation
		/// is automatically canceled.
		/// The Area Target Capture instance
		/// The configuration for the Area Target generation
		/// Optional output variable providing additional error information. Can be NULL.
		/// VU_SUCCESS if the Area Target generation has successfully started, VU_FAILED otherwise
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureGenerate(VuAreaTargetCapture* capture, VuAreaTargetCaptureGenerationConfig* config, VuAreaTargetCaptureGenerationError* error);

		/// <summary>
		/// Get status of the capture
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureGetStatus(VuAreaTargetCapture* capture, VuAreaTargetCaptureStatus* status);

		/// <summary>
		/// Get status info for the capture
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureGetStatusInfo(VuAreaTargetCapture* capture, VuAreaTargetCaptureStatusInfo* statusInfo);

		/// <summary>
		/// Cancel Area Target generation
		/// A helper function to abort a running target generation.
		/// If the target generation has been canceled successfully, then status info will hold the
		/// value
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_INFO_GENERATION_CANCELED.
		/// This function blocks until target generation has aborted
		/// This is a potentially long running operation
		/// VU_SUCCESS if the capture is in status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_GENERATING
		/// and cancelation is successful, VU_FAILED
		/// otherwise
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureCancelGeneration(VuAreaTargetCapture* capture);

		/// <summary>
		/// Get progress information of the current Area Target generation in the range [0.0f, 1.0f]
		/// VU_SUCCESS if the capture is in status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_GENERATING,
		/// VU_FAILED otherwise
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureGetGenerationProgress(VuAreaTargetCapture* capture, float* progress);

		/// <summary>
		/// Get estimated time remaining to complete the current Area Target generation in seconds
		/// It may take few seconds after the Area Target generation started for the time estimate to become available.
		/// VU_SUCCESS if the capture is in status
		/// @ref VU_AREA_TARGET_CAPTURE_STATUS_GENERATING
		/// and the time estimate is available,
		/// VU_FAILED otherwise
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureGetGenerationTimeEstimate(VuAreaTargetCapture* capture, int* remainingTimeSeconds);

		/// <summary>
		/// Destroy the given capture instance
		/// If the capture is running data acquisition, it is automatically stopped. If the capture is running target generation,
		/// it is automatically canceled.
		/// This is a potentially long running operation
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuAreaTargetCaptureDestroy(VuAreaTargetCapture* capture);

		/// <summary>
		/// Default Mesh observer configuration with Area Target Capture source
		/// Use this function to initialize the VuMeshAreaTargetCaptureConfig data structure with default values.
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuMeshAreaTargetCaptureConfig vuMeshAreaTargetCaptureConfigDefault();

		/// <summary>
		/// Create a Mesh observer with an Area Target Capture instance as source
		/// The Mesh observer will deliver Mesh observations that represent a mesh reconstruction of the environment
		/// as provided by the specified Area Target Capture instance. Because the Mesh observer is dependent on the
		/// existence of the Area Target Capture instance, one has to make sure to destroy the Mesh observer before
		/// the Area Target Capture instance is destroyed.
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuEngineCreateMeshObserverFromAreaTargetCaptureConfig(VuEngine* engine, VuObserver** observer, VuMeshAreaTargetCaptureConfig* config, VuMeshAreaTargetCaptureCreationError* errorCode);

		/// <summary>
		/// Get information about the ARCore Fusion Provider Platform
		/// The information contained in the returned struct can be used to allow applications to interact with
		/// the underlying ARCore session to gain access to functionality not currently available through the
		/// Vuforia API. For example additional lighting information or plane boundaries.
		/// Call this function after Vuforia Engine has been started and the Vuforia State
		/// contains a camera frame.
		/// If a
		/// @ref VuErrorHandler
		/// callback (passed via
		/// @ref VuErrorHandlerConfig)
		/// has been received
		/// with the error code
		/// @ref VU_ENGINE_ERROR_PLATFORM_FUSION_PROVIDER_INFO_INVALIDATED,
		/// the App must
		/// poll this API until it successfully returns the new ARCore pointers. However, this polling must not
		/// be done inside the
		/// @ref VuErrorHandler
		/// callback itself, but rather after the callback returns (i.e.
		/// the control is passed back to Vuforia Engine).
		/// Platform controller retrieved from Engine (see
		/// @ref vuEngineGetPlatformController)
		/// ARCore-specific info for the platform-based Vuforia Fusion Provider
		/// VU_FAILED if Vuforia is not running, is not using the ARCore Fusion Provider Platform,
		/// or if the ARCore pointers are not ready to be retrieved yet, VU_SUCCESS otherwise
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuPlatformControllerGetARCoreInfo(VuController* controller, VuPlatformARCoreInfo* arCoreInfo);

		/// <summary>
		/// Default iOS-specific configuration
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuPlatformiOSConfig vuPlatformiOSConfigDefault();

		/// <summary>
		/// Add an iOS-specific configuration to the engine config
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuEngineConfigSetAddPlatformiOSConfig(VuEngineConfigSet* configSet, VuPlatformiOSConfig* config);

		/// <summary>
		/// Get information about the ARKit Fusion Provider Platform
		/// The information contained in the returned struct can be used to allow applications to interact with
		/// the underlying ARKit session to gain access to functionality not currently available through the
		/// Vuforia API. For example additional lighting information or plane boundaries.
		/// Call this function after Vuforia Engine has been started and the Vuforia State
		/// contains a camera frame.
		/// Plaform controller retrieved from Engine (see
		/// @ref vuEngineGetPlatformController)
		/// ARKit-specific info for the platform-based Vuforia Fusion Provider
		/// VU_FAILED if Vuforia is not running, is not using the ARKit Fusion Provider Platform,
		/// or if the ARKit pointers are not ready to be retrieved yet, VU_SUCCESS otherwise
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuPlatformControllerGetARKitInfo(VuController* controller, VuPlatformARKitInfo* arkitInfo);

		/// <summary>
		/// Set ARKit platform fusion provider configuration
		/// This function is used to configure the ARKit session that will be used. An instance of the class
		/// ARWorldTrackingConfiguration should be created and its parameters should be set as desired.
		/// The pointer to said instance should be passed into this function. Vuforia Engine then inspects the
		/// configuration values and takes a copy of the ones that are appropriate to use with Vuforia Engine
		/// Call this function before
		/// @ref vuPlatformControllerGetARKitInfo
		/// is called for the first time.
		/// Important to notice that the setting has no effect until
		/// @ref vuPlatformControllerGetARKitInfo
		/// is called.
		/// Currently Vuforia Engine only uses the AREnvironmentTexturing option of the
		/// ARWorldTrackingConfiguration instance supplied to this call. All other configuration options
		/// are managed by Vuforia Engine.
		/// The current configuration can be found by acquiring the ARSession by using
		/// @ref vuPlatformControllerGetARKitInfo
		/// and querying the configuration from it.
		/// Platform controller retrieved from Engine (see
		/// @ref vuEngineGetPlatformController)
		/// Configuration pointer of type ARWorldTrackingConfiguration
		/// </summary>
		[DllImport("VuforiaEngine", CallingConvention = CallingConvention.StdCall)]
		public static extern VuResult vuPlatformControllerSetARKitConfig(VuController* controller, void* config);

	}
}
